SELECT *, NTILE(3) OVER (ORDER BY quantity DESC, id) AS quantity_bucket, NTILE(10) OVER (PARTITION BY store_id ORDER BY quantity, id) AS quantity_bucket_2, NTILE(5) OVER (PARTITION BY product_id, store_id ORDER BY quantity, id) AS quantity_bucket_3, SUM(quantity) OVER (PARTITION BY store_id, product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_quantity, DENSE_RANK() OVER (PARTITION BY store_id, product_id ORDER BY quantity DESC NULLS LAST) AS quantity_dense_rank FROM inventory;
